const P=Array.from({length:6},(_,k)=>ax.map(([i,j,s])=>{let t=s;if(k===5){if(i===0||j===0)t=-s;}else{const f=x=>x===k?k+1:x===k+1?k:x;i=f(i);j=f(j);if(i>j)[i,j]=[j,i];}return ax.findIndex(([a,b,c])=>a===i&&b===j&&c===t);}));
