 const bn=rows0.map(t=>t.map(BigInt)),bidx=I=>{const a=[];let k=0;while(I){if(I&3n)a.push(k);I>>=2n;k++;}return a;};
 function rank(I,need){
  if(!I)return false;let k=I*8n+BigInt(need);const use=I>>72n?cache:cacheBase;if(use.has(k))return use.get(k);
  const basis=[],pv=[];for(const j of bidx(I)){let x=bn[j].slice();for(let i=0;i<basis.length;i++){let p=pv[i],v=basis[i],a=v[p],b=x[p];if(!b)continue;x=x.map((z,c)=>a*z-b*v[c]);let g=x.reduce(gcd,0n);if(g>1n)x=x.map(z=>z/g);}
   let p=x.findIndex(t=>t!==0n);if(p>=0){basis.push(x);pv.push(p);if(basis.length>=need){use.set(k,true);return true;}}
  }use.set(k,false);return false;}
