 function clip(h,u,pos){const id=Pbits[pos];let low=[],high=[],zero=[];
  for(const v of V){let t=4096n*dot(h,v.a)-u*v.d;if(t>0n)high.push([v,t]);else if(t<0n)low.push([v,t]);else zero.push({...v,act:v.act|id});}
  if(!high.length){V=low.map(r=>r[0]).concat(zero);return;}
  const news=new Map();
  for(const [w,b]of high)for(const [v,a]of low){
   let ac=w.act&v.act,tmp=ac,n=0;while(n<5&&tmp){tmp&=tmp-1n;n++;}if(n<5||!rank(ac,5))continue;
   let g=b*v.d-a*w.d,y=v.a.map((t,i)=>b*t-a*w.a[i]),d=y.reduce(gcd,g);
   g/=d;y=y.map(t=>t/d);const key=y.join()+':'+g;if(!news.has(key))news.set(key,{a:y,d:g,act:ac|id});else news.get(key).act|=ac|id;
  }V=low.map(v=>v[0]).concat(zero,[...news.values()]);if(!V.length)throw Error('empty polyhedron');}
